from common import md, esc, cq, wq, verse_card
def eras():
    E=[("🌳","创造","创1–2","神与人立约的起点；人按神形像被造","罗1:20；罗5:12-14；林前15:45"),
       ("🍎","堕落","创3","第一亚当失败；女人后裔的应许（创3:15）","罗5:12-21；罗16:20；提前2:13-14"),
       ("🌈","挪亚","创6–9","保存世界的约；审判与拯救","彼前3:20-21；彼后2:5；3:6-7；来11:7"),
       ("⭐","亚伯拉罕","创12–22","因信称义；万国因你得福；割礼为印证","罗4；加3；来6:13-20；雅2:21-23"),
       ("⛰️","摩西 / 西奈","出19–24","律法、会幕、祭司、献祭","林后3；加3:17-24；来8–10"),
       ("👑","大卫","撒下7","永远的王位与国度","罗1:3；提后2:8；来1:5"),
       ("⛓️","被掳与先知","耶31；结36","新约应许：律法写在心上、赐新灵","林后3:3；来8:8-12；彼前1:1"),
       ("✝️","基督","福音书","应许的“是”与“阿们”（林后1:20）；十字架与复活","整卷书信的中心"),
       ("🔥","五旬节与教会","徒2","圣灵浇灌；末世已经开始","书信写作的时代（林前10:11；来1:2）"),
       ("🌅","再来与新创造","启21–22","身体复活、审判、新天新地","帖前4；林前15；彼后3:13")]
    s='<div class="eras">'
    for i,(ic,t,r,d,ep) in enumerate(E):
        s+=f'<div class="era reveal" style="--i:{i}"><span class="eic">{ic}</span><b>{t}</b><small>{r}</small><p>{d}</p><p class="epl">📨 {ep}</p></div>'
    return s+'</div>'
def twoage():
    return '''<figure class="twoage glass reveal"><svg viewBox="0 0 1000 300" role="img" aria-label="两个世代图">
<defs><linearGradient id="ta1" x1="0" x2="1"><stop offset="0" stop-color="#7c8796"/><stop offset="1" stop-color="#e0573e"/></linearGradient><linearGradient id="ta2" x1="0" x2="1"><stop offset="0" stop-color="#f5b942"/><stop offset="1" stop-color="#3fd39a"/></linearGradient></defs>
<line x1="40" y1="200" x2="720" y2="200" stroke="url(#ta1)" stroke-width="10" stroke-linecap="round"/>
<path d="M420,200 Q420,90 520,90 L960,90" fill="none" stroke="url(#ta2)" stroke-width="10" stroke-linecap="round" class="draw"/>
<rect x="420" y="80" width="300" height="130" fill="#f5b942" opacity=".10" rx="14"/>
<circle cx="420" cy="200" r="13" fill="#f5b942"/><circle cx="720" cy="200" r="13" fill="#3fd39a"/>
<text x="60" y="240" font-size="22" fill="currentColor">“今世”：罪、死亡、律法下的旧时代</text>
<text x="600" y="60" font-size="22" fill="currentColor">“来世”：新创造、圣灵、复活</text>
<text x="420" y="270" font-size="20" text-anchor="middle" fill="#f5b942">基督第一次降临 · 复活 · 五旬节</text>
<text x="720" y="245" font-size="20" text-anchor="middle" fill="#3fd39a">基督再来</text>
<text x="570" y="160" font-size="22" text-anchor="middle" fill="currentColor" font-weight="700">书信时代 = 已然 / 未然</text>
</svg><figcaption>保罗的两个世代结构（参 Geerhardus Vos《保罗的末世论》1930 的示意图，本站重绘）：信徒已经“在基督里”属于来世，却仍活在今世；书信的“直述语气”（你们已经……）先于“命令语气”（所以要……）。</figcaption></figure>'''
def covflow():
    C=[("创3:15","始约应许","女人的后裔要伤蛇的头","罗16:20"),("创9","挪亚之约","保存世界直到审判","彼后3:6-7"),("创15；17","亚伯拉罕之约","因信称义；“作你和你后裔的神”；割礼","罗4:11；加3:29"),
       ("出19–24","摩西之约","律法、会幕、献祭：影儿","加3:17,24；来10:1"),("撒下7","大卫之约","永远的王","罗1:3-4"),("耶31:31-34","新约","心版、赦罪、认识神","林后3:6；来8:6-13")]
    s='<div class="covflow">'
    for i,(r,t,d,ep) in enumerate(C):
        s+=f'<div class="cstep reveal" style="--i:{i}"><small>{r}</small><b>{t}</b><p>{d}</p><span class="cep">📨 {ep}</span></div>'+('<i class="carr">➜</i>' if i<len(C)-1 else '')
    return s+'</div><p class="note">同一个恩典之约（应许的实质都是基督），在不同时代以不同方式施行；新约是成全，不是替换另一个得救之道。</p>'
def build():
    b=[]
    b.append('<h2 id="w1">一、先跳出框架：书信在整本圣经中的位置</h2>')
    b.append('<h3 id="w1a">📚 正典中的 21 卷书信</h3>')
    b.append('<div class="canon glass reveal"><div class="cz ot"><b>旧约 39 卷</b><span>律法 · 历史 · 诗歌 · 先知</span><em>应许 · 影儿 · 预言</em></div><div class="cz gos"><b>四福音</b><span>基督的生平、死与复活</span><em>应验的事件</em></div><div class="cz act"><b>使徒行传</b><span>圣灵与教会的扩展</span><em>书信的故事框架</em></div><div class="cz ep"><b>书信 21 卷</b><span>保罗 13 · 希伯来书 · 大公 7</span><em>事件的意义与生活</em></div><div class="cz rev"><b>启示录</b><span>终局</span><em>完成</em></div></div>')
    b.append('<p>比利时信条第四条列明正典书卷，书信的排列是：</p>'+cq(("bc",4,"使徒保罗的十三卷书信，即罗马书、哥林多前后书、加拉太书、以弗所书、腓立比书、歌罗西书、帖撒罗尼迦前后书、提摩太前后书、提多书、腓利门书；希伯来书；另外还有七卷书信，即雅各书、彼得前后书、约翰一书、约翰二书、约翰三书、犹大书；")))
    b.append(f'<div class="callout key-c"><b>💡 整体观：</b>{md("福音书记载**神在基督里做了什么**，使徒行传记载**福音怎样从耶路撒冷传到罗马**，书信解释**这一切是什么意思、教会该怎样活**。书信不是零散的道德训诫，而是**使徒对基督事件的权威解释**，是“建造在使徒和先知的根基上”（{{弗2:20}}）的那根基本身。")}</div>')
    b.append('<h3 id="w1b">🧬 救赎历史主线：十个阶段</h3>'+eras())
    b.append('<h3 id="w1c">⏳ 两个世代：已然与未然</h3>'+twoage())
    b.append(f'<p>{md("“他们遭遇这些事都要作为鉴戒，并且写在经上，正是警戒我们这末世的人”（{{林前10:11}}）。“就在这末世藉着他儿子晓谕我们”（{{来1:2}}）。书信作者都意识到：**末世已经开始**，基督的复活是“初熟的果子”（{{林前15:20}}），圣灵是“得基业的凭据”（{{弗1:14}}）。这就是所有书信“已经……还没有……”张力的来源。")}</p>')
    b.append('<h2 id="w2">二、圣经神学：书信怎样读旧约</h2>')
    b.append('<h3 id="w2a">🔑 应许与应验</h3>')
    rows=[("创15:6 亚伯兰信耶和华，耶和华就以此为他的义","罗4:3；加3:6；雅2:23","因信称义的原型"),("哈2:4 义人因信得生","罗1:17；加3:11；来10:38","三次引用，三个重点：义人 / 信 / 得生"),
          ("耶31:31-34 新约","林后3；来8:8-12；10:16-17","最长的新约旧约引文"),("诗110:1,4 坐在我右边；麦基洗德","林前15:25；来1:13；5–7","升天与祭司职"),
          ("赛53 受苦的仆人","罗4:25；彼前2:22-25","代赎"),("出19:6 祭司的国度","彼前2:9","教会承接以色列身份"),("赛45:23 万膝跪拜","罗14:11；腓2:10-11","耶稣就是耶和华"),
          ("利19:18 爱人如己","罗13:9；加5:14；雅2:8","律法的总纲")]
    b.append('<div class="tbl"><table><thead><tr><th>旧约</th><th>书信</th><th>神学意义</th></tr></thead><tbody>'+"".join(f'<tr><td>{a}</td><td>{c}</td><td>{d}</td></tr>' for a,c,d in rows)+'</tbody></table></div>')
    b.append('<h3 id="w2b">🪞 影儿与实体（预表论）</h3>')
    T=[("逾越节羔羊","基督我们的逾越节羔羊","林前5:7"),("红海与云柱","受洗归了摩西","林前10:1-2"),("会幕、至圣所","天上的真帐幕","来8:5；9:11"),("大祭司","麦基洗德等次的永远大祭司","来7"),("割礼","基督的割礼与洗礼","西2:11-12"),("安息日、节期","后事的影儿，形体却是基督","西2:16-17"),("迦南安息","为神子民存留的安息","来4:9"),("挪亚方舟","洗礼的预表","彼前3:20-21")]
    b.append('<div class="types">'+"".join(f'<div class="type reveal"><span class="sh">{a}</span><i>➜</i><span class="re">{c}</span><small>{d}</small></div>' for a,c,d in T)+'</div>')
    b.append(cq(("bc",25)))
    b.append('<h3 id="w2c">🧭 救赎历史的读法（Vos · Ridderbos）</h3>')
    b.append(f'<div class="two"><div class="card glass"><h4>Geerhardus Vos（荷裔，普林斯顿）</h4><p>{md("“圣经神学”之父：启示是**有历史进程的**，随救赎行动逐步展开；书信属于启示的完成阶段（{{来1:1-2}}）。")}</p></div><div class="card glass"><h4>Herman Ridderbos（荷兰坎彭）</h4><p>{md("《保罗神学纲要》（1966）：保罗神学的中心不是单一教义，而是**基督的死与复活所开启的新时代**；称义、成圣、教会都从“与基督联合”展开。这是欧陆改革宗对保罗研究的标志性贡献。")}</p></div></div>')
    b.append('<h2 id="w3">三、圣约神学：一个恩典之约，多次施行</h2>')
    b.append('<h3 id="w3a">🤝 圣约的历史脉络</h3>'+covflow())
    b.append('<h3 id="w3b">📙 威斯敏斯特的表述（长老会改革宗）</h3>'+wq('wcf',7,6))
    b.append('<h3 id="w3c">🇳🇱 欧陆改革宗的侧重</h3>')
    b.append(f'<p>{md("三项联合信条没有像威斯敏斯特信仰告白那样单列“行为之约”一章，但在洗礼、儿女与拣选的教导中充满圣约语言：信徒的儿女“与父母同属于神的圣约和教会”（HC 74），信徒儿女“与父母共同承受恩典之约”（多特 1.17）。荷兰传统（巴文克、Klaas Schilder 等，以及 1944 年“解放”后形成、今日北美加拿大改革宗教会 canrc.org 所承接的传统）特别强调：**约包含应许与要求两面**——神应许作我们的神，也要求我们以信心与顺服回应。")}</p>')
    b.append(cq(("hc",74))+cq(("dort",1,17)))
    b.append('<h3 id="w3d">🧩 约的要素在书信中</h3>')
    R=[("立约的主动者","神（恩典的主权）","弗1:3-14；罗9:16"),("中保","耶稣基督","提前2:5；来8:6；9:15"),("应许","“我要作他们的神”","林后6:16；来8:10"),("要求","信心与顺服（信心的顺服）","罗1:5；16:26"),
       ("记号与印证","割礼→洗礼；逾越节→圣餐","罗4:11；西2:11-12；林前11:25"),("祝福与咒诅","在基督里得福；背约者受更重的刑罚","加3:13-14；来10:28-29"),("立约群体","信徒与他们的儿女","林前7:14；弗6:1-4；提后1:5")]
    b.append('<div class="tbl"><table><thead><tr><th>要素</th><th>内容</th><th>书信经文</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{d}</td></tr>' for a,c,d in R)+'</tbody></table></div>')
    b.append('<h3 id="w3e">⚖️ 律法与福音、律法的用处</h3>')
    b.append(f'<p>{md("改革宗区分“律法与福音”，但不把二者对立：律法在恩典之约里有三重用处——使人知罪而归向基督（{{罗3:20}}；{{加3:24}}）、约束社会的罪恶（{{提前1:9-10}}）、作感恩生活的准则（{{雅1:25}}；{{罗13:8-10}}）。海德堡要理问答第三部分（感恩）就把十诫放在“得救之后”。")}</p>')
    b.append(cq(("hc",115))+wq('wcf',19,6,"六、虽然真信徒不在行为之约的律法之下，不因此被称义或定罪。但律法无论是对他们还是其他人都有很大的用处。因为作为生活的准则，律法显明神的旨意和人的责任，约束人或指引人照着去做。"))
    b.append('<h2 id="w4">四、欧陆改革宗的读法</h2>')
    b.append('<h3 id="w4a">📖 唯独圣经与以经解经</h3>'+cq(("bc",7,"我们相信，圣经中包含了神全部的旨意；我们也相信它对人得救所必须信的一切真理作了充分的教导。"))+wq('wcf',1,9,"九、在解释《圣经》时，唯一无错谬的原则是「以经解经」。"))
    b.append('<h3 id="w4b">🔺 海德堡三段式 = 罗马书的骨架</h3>')
    b.append(cq(("hc",2)))
    b.append('<div class="tri"><div class="tr t1 reveal"><b>① 罪与愁苦</b><span>HC 3–11</span><p>罗 1:18–3:20</p><small>林前 1–6 的败坏；弗 2:1-3</small></div><div class="tr t2 reveal"><b>② 救赎</b><span>HC 12–85</span><p>罗 3:21–11:36</p><small>加 2–4；来 1–10；彼前 1</small></div><div class="tr t3 reveal"><b>③ 感恩</b><span>HC 86–129</span><p>罗 12–16</p><small>弗 4–6；西 3–4；雅；彼前 2–5</small></div></div>')
    b.append('<h3 id="w4c">🌷 多特五要点与书信</h3>')
    D=[("全然败坏","第三、四项","罗3:10-18；弗2:1-3"),("无条件拣选","第一项","弗1:4-5；罗9:11-16；帖后2:13"),("有效的救赎（限定的救赎）","第二项","弗5:25；来9:15；多2:14"),("不可抗拒的恩典（有效的呼召）","第三、四项","罗8:30；林后4:6；雅1:18"),("圣徒的坚忍（蒙保守）","第五项","腓1:6；彼前1:5；犹24")]
    b.append('<div class="tbl"><table><thead><tr><th>要点</th><th>多特信经</th><th>书信经文</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{d}</td></tr>' for a,c,d in D)+'</tbody></table></div><p class="note">“TULIP”是后来英语世界的记忆缩写，多特信经本身的次序是：拣选 → 基督的死 → 人的败坏与归正 → 坚忍。</p>')
    b.append('<h2 id="w5">五、书信的体裁与读法</h2>')
    b.append('<h3 id="w5a">✉️ 一封古代书信的结构</h3>')
    L=[("发信人","保罗，奉神旨意作基督耶稣使徒的"),("收信人","写信给……圣徒"),("问安","愿恩惠、平安归与你们"),("感恩/颂赞","我感谢神……"),("正文","教义与回应问题"),("劝勉","所以……"),("问候与差派","代我问……安"),("祝福","愿主耶稣基督的恩常与你们同在")]
    b.append('<div class="letter">'+"".join(f'<div class="lp reveal" style="--i:{i}"><b>{a}</b><span>{c}</span></div>' for i,(a,c) in enumerate(L))+'</div>')
    b.append(f'<div class="callout"><b>🔄 直述 → 命令：</b>{md("“你们是……”（身份）先于“所以要……”（责任）。罗马书 1–11 → 12–16；以弗所书 1–3 → 4–6；歌罗西书 1–2 → 3–4。**福音的次序不可颠倒：恩典先于责任，感恩产生顺服。**")}</div>')
    b.append('<h3 id="w5b">👁️ 八个视角读书信</h3>')
    V=[("🏛️","历史","作者、读者、城市、事件"),("✍️","文学","书信结构、修辞、论证"),("📜","救赎历史","在整本圣经故事中的位置"),("🤝","圣约","应许、记号、群体、要求"),("📘","教义","与信条对照、系统神学"),("⛪","教会","敬拜、职分、纪律、合一"),("🌱","伦理","家庭、工作、社会、苦难"),("🌅","末世","已然未然、盼望")]
    b.append('<div class="views">'+"".join(f'<div class="view reveal"><span>{a}</span><b>{c}</b><p>{d}</p></div>' for a,c,d in V)+'</div>')
